// SandboxRouterServiceHandler is an implementation of the bugnet.router.v1.SandboxRouterService
// service.
type SandboxRouterServiceHandler interface {
	Estimate(context.Context, *connect.Request[v1.EstimateRequest]) (*connect.Response[v1.EstimateResponse], error)
	// Prices a start package as a start would find it now, spending no quote limit, writing no row
	PricePackage(context.Context, *connect.Request[v1.PricePackageRequest]) (*connect.Response[v1.PricePackageResponse], error)
	CreatePlacement(context.Context, *connect.Request[v1.CreatePlacementRequest]) (*connect.Response[v1.CreatePlacementResponse], error)
	GetPlacement(context.Context, *connect.Request[v1.GetPlacementRequest]) (*connect.Response[v1.GetPlacementResponse], error)
	WatchPlacement(context.Context, *connect.Request[v1.WatchPlacementRequest], *connect.ServerStream[v1.WatchPlacementResponse]) error
	ExtendPlacement(context.Context, *connect.Request[v1.ExtendPlacementRequest]) (*connect.Response[v1.ExtendPlacementResponse], error)
	CheckExtendPlacement(context.Context, *connect.Request[v1.CheckExtendPlacementRequest]) (*connect.Response[v1.CheckExtendPlacementResponse], error)
	ListExtensions(context.Context, *connect.Request[v1.ListExtensionsRequest]) (*connect.Response[v1.ListExtensionsResponse], error)
	StopPlacement(context.Context, *connect.Request[v1.StopPlacementRequest]) (*connect.Response[v1.StopPlacementResponse], error)
	Exec(context.Context, *connect.Request[v1.ExecRequest]) (*connect.Response[v1.ExecResponse], error)
	WatchJob(context.Context, *connect.Request[v1.WatchJobRequest], *connect.ServerStream[v1.WatchJobResponse]) error
	CancelJob(context.Context, *connect.Request[v1.CancelJobRequest]) (*connect.Response[v1.CancelJobResponse], error)
	ReadFile(context.Context, *connect.Request[v1.ReadFileRequest]) (*connect.Response[v1.ReadFileResponse], error)
	WriteFile(context.Context, *connect.Request[v1.WriteFileRequest]) (*connect.Response[v1.WriteFileResponse], error)
	ListFiles(context.Context, *connect.Request[v1.ListFilesRequest]) (*connect.Response[v1.ListFilesResponse], error)
	CreatePreview(context.Context, *connect.Request[v1.CreatePreviewRequest]) (*connect.Response[v1.CreatePreviewResponse], error)
	CreateTransfer(context.Context, *connect.Request[v1.CreateTransferRequest]) (*connect.Response[v1.CreateTransferResponse], error)
	AddSshKey(context.Context, *connect.Request[v1.AddSshKeyRequest]) (*connect.Response[v1.AddSshKeyResponse], error)
	RemoveSshKey(context.Context, *connect.Request[v1.RemoveSshKeyRequest]) (*connect.Response[v1.RemoveSshKeyResponse], error)
	CreateSecretLink(context.Context, *connect.Request[v1.CreateSecretLinkRequest]) (*connect.Response[v1.CreateSecretLinkResponse], error)
	// A 10-minute grant the bridge sends to the secrets route instead of the handle
	CreateSecretPutGrant(context.Context, *connect.Request[v1.CreateSecretPutGrantRequest]) (*connect.Response[v1.CreateSecretPutGrantResponse], error)
	GetSecretSealingKey(context.Context, *connect.Request[v1.GetSecretSealingKeyRequest]) (*connect.Response[v1.GetSecretSealingKeyResponse], error)
	PutSecret(context.Context, *connect.Request[v1.PutSecretRequest]) (*connect.Response[v1.PutSecretResponse], error)
	ListSecrets(context.Context, *connect.Request[v1.ListSecretsRequest]) (*connect.Response[v1.ListSecretsResponse], error)
	DeleteSecret(context.Context, *connect.Request[v1.DeleteSecretRequest]) (*connect.Response[v1.DeleteSecretResponse], error)
	// Puts the placement's GitHub source in the sandbox, safe to call again
	FetchSource(context.Context, *connect.Request[v1.FetchSourceRequest]) (*connect.Response[v1.FetchSourceResponse], error)
	// Checks an x402 change without making it, and with no handle only what needs no placement
	CheckX402(context.Context, *connect.Request[v1.CheckX402Request]) (*connect.Response[v1.CheckX402Response], error)
	// Stores x402 services and applies them to the sandbox, idempotent by content
	EnableX402(context.Context, *connect.Request[v1.EnableX402Request]) (*connect.Response[v1.EnableX402Response], error)
	// Lists the placement's x402 services with their states and counts, and its refusals
	ListX402(context.Context, *connect.Request[v1.ListX402Request]) (*connect.Response[v1.ListX402Response], error)
}

